 201│                                fallback: defaultRoles.binding(for: .coder),
 202│                                learning: learning, language: language)
 203│             let critic = choose(for: .critic, profile: profile, snapshot: snapshot,
 204│                                 fallback: defaultRoles.binding(for: .critic), avoid: coder.binding.providerId,
 205│                                 learning: learning, language: language)
 206│             let worker = choose(for: profile.prefersResearch ? .worker : .coder, profile: profile,
 207│                                 snapshot: snapshot, fallback: defaultRoles.binding(for: .worker),
 208│                                 learning: learning, language: language)
 209│ 
 210│             var roles = RoleBindings(default: worker.binding)
 211│                 .binding(.planner, to: planner.binding)
 212│                 .binding(.worker, to: worker.binding)
 213│                 .binding(.coder, to: coder.binding)
 214│                 .binding(.critic, to: critic.binding)
 215│ 
 216│             // Keep user-provided heterogeneous teams as a floor when the scorer has no candidates.
 217│             if snapshot.providers.isEmpty { roles = defaultRoles }
