 282│     private static func choose(for role: RoleTarget, profile: TaskProfile, snapshot: ProjectSnapshot,
 283│                                fallback: ProviderBinding, avoid: String? = nil,
 284│                                learning: ModelAssignmentLearningContext? = nil,
 285│                                language: String? = nil) -> Scored {
 286│         let fallbackEvidence = learning?.evidence(providerId: fallback.providerId, role: role.learningRole,
 287│                                                   taskTags: profile.tags, language: language)
 288│         var best = Scored(binding: fallback,
 289│                           score: 45 + (fallbackEvidence?.scoreBoost ?? 0),
 290│                           learningEvidence: fallbackEvidence)
 291│         for candidate in snapshot.providers {
 292│             let evidence = learning?.evidence(providerId: candidate.binding.providerId,
 293│                                               role: role.learningRole,
 294│                                               taskTags: profile.tags,
 295│                                               language: language)
 296│             let score = score(candidate, for: role, profile: profile,
 297│                               defaultProvider: fallback.providerId, avoid: avoid,
 298│                               learningEvidence: evidence)
 299│             if score > best.score {
 300│                 best = Scored(binding: candidate.binding, score: score, learningEvidence: evidence)
 301│             }
 302│         }
 303│         return best
 304│     }
