 306│     private static func score(_ candidate: ProjectSnapshot.ProviderCandidate, for role: RoleTarget,
 307│                               profile: TaskProfile, defaultProvider: String, avoid: String?,
 308│                               learningEvidence: CaptainLearningSummary?) -> Double {
 309│         let id = candidate.binding.providerId.lowercased()
 310│         let model = (candidate.binding.model ?? "").lowercased()
 311│         let caps = candidate.capabilities
 312│         var score: Double = candidate.keyed ? 40 : 0
 313│         if id == defaultProvider.lowercased() { score += 4 }
 314│         if let avoid, id == avoid.lowercased() { score -= 8 }
 315│         if let ctx = caps.contextWindowTokens { score += min(12, Double(ctx) / 100_000.0) }
 316│         if caps.nativeTools { score += 5 }
 317│         if caps.structuredOutput { score += 4 }
 318│         if profile.wantsReasoning && caps.reasoning { score += 12 }
 319│         if profile.wantsVision && (caps.vision || caps.video || caps.audio) { score += 18 }
 320│         if profile.prefersResearch && (caps.grounding || caps.urlContext || caps.deepResearch) { score += 16 }
 321│         if model.contains("flash") || model.contains("mini") || model.contains("lite") { score += role == .worker ? 4 : -3 }
 322│         score += learningEvidence?.scoreBoost ?? 0
 323│ 
 324│         switch role {
 325│         case .planner:
 326│             score += preference(id, ["openai": 12, "gemini": 11, "mimo": 10, "deepseek": 9, "anthropic": 8])
 327│             if caps.reasoning { score += 8 }
 328│         case .worker:
 329│             score += preference(id, ["deepseek": 11, "mimo": 10, "qwen": 9, "gemini": 8, "ollama": 6, "mlx": 6])
 330│             if profile.prefersResearch { score += preference(id, ["gemini": 10, "openai": 8, "perplexity": 14]) }
 331│         case .coder:
 332│             score += preference(id, ["deepseek": 14, "mimo": 13, "qwen": 10, "openai": 9, "anthropic": 8, "mlx": 7])
 333│             if caps.codeExecution { score += 8 }
 334│         case .critic:
 335│             score += preference(id, ["gemini": 13, "openai": 12, "anthropic": 11, "deepseek": 8, "mimo": 7])
 336│             if caps.reasoning { score += 7 }
 337│         }
 338│         return score
 339│     }
